export interface Frontmatter {
  title?: string;
  date?: string;
  tags?: string[];
}

export interface Page {
  slug: string;
  title: string;
  date?: string;
  tags: string[];
  html: string;
  sourcePath: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

export interface BuildResult {
  pages: Page[];
  outputDir: string;
}

import matter from 'gray-matter';

export interface ParsedMarkdown {
  data: Record<string, unknown>;
  content: string;
}

const FRONTMATTER_RE = /^---[ \t]*\r?\n([\s\S]*?)\r?\n---[ \t]*(?:\r?\n|$)/;

function stripBom(raw: string): string {
  return raw.charCodeAt(0) === 0xfeff ? raw.slice(1) : raw;
}

/**
 * Parse a raw Markdown file: extract YAML frontmatter (if present) and return
 * the parsed data alongside the remaining Markdown body.
 *
 * The frontmatter block is stripped manually with a regex before the body is
 * handed to a Markdown parser, so `---` delimiters are never rendered as HTML.
 */
export function parseMarkdown(raw: string): ParsedMarkdown {
  const text = stripBom(raw);
  const match = text.match(FRONTMATTER_RE);

  if (!match) {
    return { data: {}, content: text };
  }

  const yaml = match[1];
  const content = text.slice(match[0].length);
  const parsed = matter(`---\n${yaml}\n---`);

  return { data: parsed.data, content };
}

import fs from 'fs';
import path from 'path';
import { marked } from 'marked';
import { parseMarkdown } from './frontmatter';
import type { BuildOptions, BuildResult, Page } from './types';

const MARKDOWN_EXTENSIONS = ['.md', '.markdown'];

export function build(options: BuildOptions): BuildResult {
  const { contentDir, outputDir } = options;
  const pages = readPages(contentDir);

  fs.mkdirSync(outputDir, { recursive: true });

  for (const page of pages) {
    const pageHtml = renderPage(page);
    fs.writeFileSync(path.join(outputDir, `${page.slug}.html`), pageHtml);
  }

  const indexHtml = renderIndex(pages);
  fs.writeFileSync(path.join(outputDir, 'index.html'), indexHtml);

  return { pages, outputDir };
}

function readPages(contentDir: string): Page[] {
  if (!fs.existsSync(contentDir)) {
    throw new Error(`Content directory not found: ${contentDir}`);
  }

  const entries = fs.readdirSync(contentDir);
  const pages: Page[] = [];

  for (const entry of entries.sort()) {
    const ext = path.extname(entry);
    if (!MARKDOWN_EXTENSIONS.includes(ext)) continue;

    const filePath = path.join(contentDir, entry);
    const raw = fs.readFileSync(filePath, 'utf-8');
    const { data, content } = parseMarkdown(raw);
    const slug = slugify(entry);

    pages.push({
      slug,
      title: typeof data.title === 'string' && data.title.trim() !== '' ? data.title : slug,
      date: typeof data.date === 'string' ? data.date : undefined,
      tags: normalizeTags(data.tags),
      html: marked.parse(content) as string,
      sourcePath: filePath,
    });
  }

  return pages;
}

function slugify(filename: string): string {
  return path.basename(filename, path.extname(filename));
}

function normalizeTags(tags: unknown): string[] {
  if (Array.isArray(tags)) {
    return tags.map((tag) => String(tag).trim()).filter(Boolean);
  }
  if (typeof tags === 'string') {
    return tags
      .split(',')
      .map((tag) => tag.trim())
      .filter(Boolean);
  }
  return [];
}

function renderPage(page: Page): string {
  const tagsMarkup = page.tags.length
    ? `<ul class="tags">${page.tags.map((tag) => `<li>${escapeHtml(tag)}</li>`).join('')}</ul>`
    : '';
  const dateMarkup = page.date ? `<p class="date">${escapeHtml(page.date)}</p>` : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(page.title)}</title>
</head>
<body>
  <header>
    <h1>${escapeHtml(page.title)}</h1>
${dateMarkup}
${tagsMarkup}
  </header>
  <nav><a href="index.html">&larr; All posts</a></nav>
  <article>
${page.html}
  </article>
</body>
</html>
`;
}

function renderIndex(pages: Page[]): string {
  const sorted = [...pages].sort(byDateDesc);
  const items = sorted
    .map((page) => {
      const meta = [page.date, page.tags.length ? page.tags.join(', ') : '']
        .filter(Boolean)
        .join(' \u2014 ');
      const metaMarkup = meta ? ` <span class="meta">${escapeHtml(meta)}</span>` : '';
      return `    <li><a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.title)}</a>${metaMarkup}</li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>All Posts</title>
</head>
<body>
  <header>
    <h1>All Posts</h1>
  </header>
  <ul>
${items}
  </ul>
</body>
</html>
`;
}

function byDateDesc(a: Page, b: Page): number {
  if (!a.date && !b.date) return a.title.localeCompare(b.title);
  if (!a.date) return 1;
  if (!b.date) return -1;
  return b.date.localeCompare(a.date);
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

#!/usr/bin/env node
import { build } from './ssg';

export interface CliOptions {
  command: string;
  contentDir: string;
  outputDir: string;
}

export function parseArgs(argv: string[]): CliOptions {
  const args = argv.slice(2);
  let command = 'build';
  let contentDir = './content';
  let outputDir = './dist';
  const positionals: string[] = [];

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--content' || arg === '-c') {
      contentDir = args[++i] ?? contentDir;
    } else if (arg === '--output' || arg === '-o') {
      outputDir = args[++i] ?? outputDir;
    } else if (arg.startsWith('--content=')) {
      contentDir = arg.slice('--content='.length);
    } else if (arg.startsWith('--output=')) {
      outputDir = arg.slice('--output='.length);
    } else if (!arg.startsWith('-')) {
      positionals.push(arg);
    }
  }

  if (positionals.length > 0) {
    command = positionals[0];
  }

  return { command, contentDir, outputDir };
}

export function run(argv: string[]): number {
  const opts = parseArgs(argv);

  if (opts.command !== 'build') {
    console.error(`Unknown command: ${opts.command}`);
    return 1;
  }

  try {
    const result = build({ contentDir: opts.contentDir, outputDir: opts.outputDir });
    console.log(`Generated ${result.pages.length} page(s) in ${opts.outputDir}`);
    return 0;
  } catch (err) {
    console.error((err as Error).message);
    return 1;
  }
}

if (require.main === module) {
  process.exit(run(process.argv));
}

